{
  "ok": true,
  "startedAt": "2026-10-13T15:16:54.246Z",
  "blockers": [],
  "catalog": {
    "version": 1,
    "capabilitySet": "primitives-6.ops-18.limits-64-512",
    "primitives": [
      "cube",
      "uv_sphere",
      "cylinder",
      "cone",
      "torus",
      "plane"
    ],
    "limits": {
      "maxOpsPerBatch": 64,
      "maxObjects": 512,
      "nameCharset": "A-Za-z0-9_-.",
      "nameMaxLength": 96
    },
    "ops": {
      "mesh.revolve_profile": {
        "mutates": false,
        "destructive": false,
        "summary": "revolve a closed [radius,height] profile around Z, in metres; include outer wall, rim, inner wall and bottom to create a genuinely hollow cup, not a solid cylinder; smooth shaded",
        "args": {
          "name": {
            "type": "string",
            "required": true
          },
          "profile": {
            "type": "array",
            "required": true,
            "note": "3..128 [radius,height] pairs, radius>=0, closed implicitly (do NOT repeat first point); axes r,z; heights and radii in metres"
          },
          "segments": {
            "type": "number",
            "default": 96,
            "range": "integer 16..128"
          },
          "location": {
            "type": "vec3",
            "default": [
              0,
              0,
              0
            ]
          },
          "material": {
            "type": "string",
            "optional": true
          },
          "replace": {
            "type": "boolean",
            "default": false
          }
        },
        "example": {
          "op": "mesh.revolve_profile",
          "args": {
            "name": "cup",
            "profile": [
              [
                0,
                0
              ],
              [
                0.03,
                0
              ],
              [
                0.05,
                0.08
              ],
              [
                0.047,
                0.08
              ],
              [
                0.027,
                0.005
              ],
              [
                0,
                0.005
              ]
            ],
            "segments": 96
          }
        }
      },
      "mesh.sweep_tube": {
        "mutates": false,
        "destructive": false,
        "summary": "smooth tube swept along 3..64 numeric centreline points in metres; use an open C-shaped path with ends touching the cup wall for a natural handle",
        "args": {
          "name": {
            "type": "string",
            "required": true
          },
          "points": {
            "type": "array",
            "required": true,
            "note": "3..64 [x,y,z] triples, bounded ±1000m"
          },
          "radius": {
            "type": "number",
            "required": true,
            "range": "(0,1000]m"
          },
          "location": {
            "type": "vec3",
            "default": [
              0,
              0,
              0
            ]
          },
          "material": {
            "type": "string",
            "optional": true
          },
          "replace": {
            "type": "boolean",
            "default": false
          }
        },
        "example": {
          "op": "mesh.sweep_tube",
          "args": {
            "name": "handle",
            "points": [
              [
                0.05,
                0,
                0.07
              ],
              [
                0.075,
                0,
                0.08
              ],
              [
                0.09,
                0,
                0.055
              ],
              [
                0.075,
                0,
                0.02
              ],
              [
                0.04,
                0,
                0.02
              ]
            ],
            "radius": 0.005
          }
        }
      },
      "mesh.primitive_add": {
        "mutates": false,
        "summary": "add one primitive mesh",
        "args": {
          "kind": {
            "type": "enum",
            "required": true,
            "values": [
              "cube",
              "uv_sphere",
              "cylinder",
              "cone",
              "torus",
              "plane"
            ]
          },
          "name": {
            "type": "string",
            "required": true,
            "charset": "A-Za-z0-9_-.",
            "maxLength": 96
          },
          "size": {
            "type": "number",
            "default": 1,
            "range": "(0, 1000]",
            "note": "diameter/footprint"
          },
          "location": {
            "type": "vec3",
            "default": [
              0,
              0,
              0
            ],
            "absMax": 10000
          },
          "rotation_euler": {
            "type": "vec3",
            "default": [
              0,
              0,
              0
            ],
            "unit": "radians"
          },
          "scale": {
            "type": "vec3",
            "default": [
              1,
              1,
              1
            ],
            "range": "(0, 10000]"
          },
          "material": {
            "type": "string",
            "optional": true,
            "note": "created on demand"
          },
          "replace": {
            "type": "boolean",
            "default": false,
            "note": "overwrite an existing object of the same name"
          }
        },
        "example": {
          "op": "mesh.primitive_add",
          "args": {
            "kind": "uv_sphere",
            "name": "head",
            "size": 1.6,
            "location": [
              0,
              0,
              3.3
            ],
            "material": "Skin"
          }
        }
      },
      "object.transform": {
        "mutates": true,
        "summary": "set absolute location / rotation_euler / scale",
        "args": {
          "name": {
            "type": "string",
            "required": true
          },
          "location": {
            "type": "vec3",
            "optional": true,
            "absMax": 10000
          },
          "rotation_euler": {
            "type": "vec3",
            "optional": true,
            "unit": "radians"
          },
          "scale": {
            "type": "vec3",
            "optional": true,
            "range": "(0, 10000]"
          }
        },
        "notes": [
          "at least one of location/rotation_euler/scale is required",
          "values are absolute, not deltas",
          "rotation_euler switches the object to XYZ mode first when it is not already in an euler mode -- a glTF import arrives as QUATERNION, where rotation_euler would be silently ignored -- and the return reports rotationMode before/after"
        ],
        "example": {
          "op": "object.transform",
          "args": {
            "name": "arm_L",
            "rotation_euler": [
              0,
              0,
              -0.35
            ]
          }
        }
      },
      "object.duplicate": {
        "mutates": false,
        "summary": "copy an object (cheapest way to build mirrored limbs)",
        "args": {
          "name": {
            "type": "string",
            "required": true,
            "note": "source"
          },
          "newName": {
            "type": "string",
            "required": true,
            "charset": "A-Za-z0-9_-.",
            "maxLength": 96
          },
          "offset": {
            "type": "vec3",
            "optional": true,
            "note": "relative to the source location"
          },
          "scale": {
            "type": "vec3",
            "optional": true,
            "range": "(0, 10000]"
          }
        },
        "example": {
          "op": "object.duplicate",
          "args": {
            "name": "body",
            "newName": "arm_R",
            "offset": [
              -0.85,
              0,
              0.15
            ]
          }
        }
      },
      "object.delete": {
        "mutates": true,
        "destructive": true,
        "summary": "remove an object",
        "args": {
          "name": {
            "type": "string",
            "required": true
          }
        },
        "example": {
          "op": "object.delete",
          "args": {
            "name": "Cube"
          }
        }
      },
      "material.set": {
        "mutates": false,
        "summary": "create a material if missing, then set colour/roughness/metallic/emission",
        "args": {
          "name": {
            "type": "string",
            "required": true
          },
          "color": {
            "type": "vec3",
            "default": [
              0.8,
              0.8,
              0.8
            ],
            "range": "0..1 per channel"
          },
          "roughness": {
            "type": "number",
            "optional": true,
            "range": "0..1"
          },
          "metallic": {
            "type": "number",
            "optional": true,
            "range": "0..1"
          },
          "emission": {
            "type": "number",
            "optional": true,
            "note": "emission strength, 0..1 typical"
          }
        },
        "notes": [
          "colour is linear scene-referred, not sRGB hex; divide a hex value by 255 and apply an approximate sRGB->linear step for similar-looking results"
        ],
        "example": {
          "op": "material.set",
          "args": {
            "name": "Hair",
            "color": [
              0.12,
              0.18,
              0.55
            ],
            "roughness": 0.45
          }
        }
      },
      "material.assign": {
        "mutates": true,
        "summary": "replace all material slots of an object with one material",
        "args": {
          "name": {
            "type": "string",
            "required": true,
            "note": "object"
          },
          "material": {
            "type": "string",
            "required": true
          }
        },
        "example": {
          "op": "material.assign",
          "args": {
            "name": "head",
            "material": "Skin"
          }
        }
      },
      "object.join": {
        "mutates": true,
        "destructive": true,
        "summary": "merge several objects into the first one",
        "args": {
          "names": {
            "type": "strlist",
            "required": true,
            "minItems": 2,
            "maxItems": 64
          },
          "name": {
            "type": "string",
            "required": true
          }
        },
        "example": {
          "op": "object.join",
          "args": {
            "names": [
              "arm_L",
              "arm_R"
            ],
            "name": "arms"
          }
        }
      },
      "modifier.add": {
        "mutates": true,
        "destructive": false,
        "summary": "add an unapplied modifier to a mesh object",
        "args": {
          "name": {
            "type": "string",
            "required": true,
            "note": "the mesh object"
          },
          "kind": {
            "type": "enum",
            "values": [
              "subdivision",
              "bevel",
              "mirror",
              "solidify"
            ],
            "required": true
          },
          "amount": {
            "type": "number",
            "optional": true,
            "note": "subdivision levels (1-6, integer), bevel width, or solidify thickness"
          },
          "segments": {
            "type": "integer",
            "optional": true,
            "range": "1..16",
            "note": "bevel only"
          },
          "axis": {
            "type": "enum",
            "values": [
              "X",
              "Y",
              "Z"
            ],
            "optional": true,
            "note": "mirror only"
          }
        },
        "refuses": [
          "E_NO_SUCH_OBJECT",
          "E_NOT_A_MESH",
          "E_ARG_ENUM",
          "E_ARG_RANGE",
          "E_LIMIT"
        ],
        "note": "left unapplied so it stays editable in the modifier stack; nothing is baked",
        "example": {
          "op": "modifier.add",
          "args": {
            "name": "body",
            "kind": "bevel",
            "amount": 0.02,
            "segments": 3
          }
        }
      },
      "light.add": {
        "mutates": true,
        "destructive": false,
        "summary": "add a light",
        "args": {
          "kind": {
            "type": "enum",
            "values": [
              "point",
              "sun",
              "area",
              "spot"
            ],
            "default": "point"
          },
          "name": {
            "type": "string",
            "optional": true
          },
          "energy": {
            "type": "number",
            "optional": true,
            "note": "W/m^2 for sun, W otherwise; defaults are per kind"
          },
          "color": {
            "type": "vec3",
            "optional": true,
            "range": "0..1 per channel"
          },
          "size": {
            "type": "number",
            "optional": true,
            "note": "area lights only"
          },
          "location": {
            "type": "vec3",
            "optional": true,
            "default": [
              0,
              0,
              4
            ]
          },
          "rotation_euler": {
            "type": "vec3",
            "optional": true,
            "unit": "radians"
          },
          "replace": {
            "type": "boolean",
            "default": false
          }
        },
        "refuses": [
          "E_NAME_TAKEN",
          "E_ARG_ENUM",
          "E_ARG_RANGE",
          "E_ARG_TYPE"
        ],
        "example": {
          "op": "light.add",
          "args": {
            "kind": "sun",
            "name": "KeyLight",
            "energy": 4,
            "location": [
              4,
              -4,
              8
            ]
          }
        }
      },
      "camera.add": {
        "mutates": true,
        "destructive": false,
        "summary": "add a camera (perspective by default, orthographic on request) and optionally make it the scene camera; the return carries type, ortho_scale, sensorFit, resolution and metresPerPixel",
        "args": {
          "name": {
            "type": "string",
            "optional": true
          },
          "type": {
            "type": "enum",
            "values": [
              "PERSP",
              "ORTHO"
            ],
            "default": "PERSP",
            "note": "ORTHO pins sensor_fit to VERTICAL so ortho_scale always means the world height of the frame; AUTO would follow whichever image side is longer"
          },
          "ortho_scale": {
            "type": "number",
            "optional": true,
            "range": "(0, 100000] metres",
            "note": "required when type is ORTHO, refused when type is PERSP"
          },
          "lens": {
            "type": "number",
            "optional": true,
            "range": "1..500 mm",
            "default": 50,
            "note": "kept on the data block, but has no effect while type is ORTHO"
          },
          "location": {
            "type": "vec3",
            "optional": true,
            "default": [
              0,
              -6,
              3
            ]
          },
          "rotation_euler": {
            "type": "vec3",
            "optional": true,
            "unit": "radians"
          },
          "active": {
            "type": "boolean",
            "default": true,
            "note": "assign it as scene.camera"
          },
          "replace": {
            "type": "boolean",
            "default": false
          }
        },
        "refuses": [
          "E_NAME_TAKEN",
          "E_ARG_RANGE",
          "E_ARG_TYPE",
          "E_ARG_ENUM",
          "E_ARG_MISSING",
          "E_ARG_CONFLICT"
        ],
        "example": {
          "op": "camera.add",
          "args": {
            "name": "Front",
            "type": "ORTHO",
            "ortho_scale": 2.4,
            "location": [
              0,
              -8,
              1
            ],
            "rotation_euler": [
              1.5707963,
              0,
              0
            ]
          }
        }
      },
      "render.still": {
        "mutates": true,
        "destructive": false,
        "summary": "render scene.camera to a .png on disk (capture renders the viewport instead); returns path, sha256, bytes, width, height, ortho_scale, sensor_fit, metresPerPixel and camera_pose (name/location/rotation_euler/rotation_mode/rotation_effective) -- never an image block",
        "args": {
          "camera": {
            "type": "string",
            "required": true,
            "note": "the camera to render with; it becomes scene.camera"
          },
          "width": {
            "type": "number",
            "required": true,
            "range": "1..16384 pixels"
          },
          "height": {
            "type": "number",
            "required": true,
            "range": "1..16384 pixels"
          },
          "path": {
            "type": "string",
            "required": true,
            "note": "absolute .png path; an existing file is overwritten and the return says so"
          },
          "transparent": {
            "type": "boolean",
            "default": false,
            "note": "film_transparent: the silhouette is alpha>0, which needs no background-colour guess"
          }
        },
        "refuses": [
          "E_ARG_MISSING",
          "E_NO_SUCH_OBJECT",
          "E_NOT_A_CAMERA",
          "E_UNSUPPORTED_FORMAT",
          "E_ARG_RANGE",
          "E_INTERNAL"
        ],
        "example": {
          "op": "render.still",
          "args": {
            "camera": "Front",
            "width": 512,
            "height": 512,
            "path": "D:/work/renders/front-512.png",
            "transparent": true
          }
        }
      },
      "object.look_at": {
        "mutates": true,
        "destructive": false,
        "summary": "aim an object (camera or light) at a point or at another object",
        "notes": [
          "switches the object to XYZ mode first when it is not in an euler mode, and reports rotationMode before/after, for the same reason object.transform does"
        ],
        "args": {
          "name": {
            "type": "string",
            "required": true
          },
          "target": {
            "type": "string or vec3",
            "required": true,
            "note": "an object name, or a world point"
          }
        },
        "refuses": [
          "E_NO_SUCH_OBJECT",
          "E_ARG_RANGE",
          "E_ARG_TYPE"
        ],
        "note": "both lights and cameras look down their own -Z with +Y up, so one aim serves both",
        "example": {
          "op": "object.look_at",
          "args": {
            "name": "Shot",
            "target": "body"
          }
        }
      },
      "mesh.import": {
        "mutates": true,
        "destructive": false,
        "summary": "import an external mesh (.glb/.gltf/.obj) into the managed scene",
        "args": {
          "path": {
            "type": "string",
            "required": true,
            "note": "absolute, or relative to the working directory; the file must exist"
          },
          "name": {
            "type": "string",
            "optional": true,
            "note": "rename the largest imported mesh"
          },
          "upAxis": {
            "type": "enum",
            "values": [
              "X",
              "Y",
              "Z"
            ],
            "default": "Y",
            "note": "the up axis the FILE uses, declared by the caller; this op never guesses it"
          },
          "scale": {
            "type": "number",
            "default": 1,
            "range": "(0, 1000]",
            "note": "file space -> metres"
          },
          "size": {
            "type": "vec3",
            "optional": true,
            "note": "expected final size; compared and reported, never applied"
          },
          "location": {
            "type": "vec3",
            "optional": true,
            "note": "expected final centre; compared and reported, never applied"
          },
          "bytes": {
            "type": "integer",
            "optional": true,
            "note": "declared file size; a mismatch refuses with E_BYTE_MISMATCH"
          },
          "sha256": {
            "type": "string",
            "optional": true,
            "note": "declared digest; a mismatch refuses with E_BYTE_MISMATCH"
          }
        },
        "refuses": [
          "E_NO_SUCH_FILE",
          "E_UNSUPPORTED_FORMAT",
          "E_BYTE_MISMATCH",
          "E_NO_MESH_IMPORTED"
        ],
        "note": "A refusal leaves the scene untouched (non-mesh leftovers are removed). The glTF importer has no axis parameter, so a declared up axis other than Y is corrected by rotating the imported objects; OBJ passes the declared axis straight to its importer with a fixed -Y forward axis.",
        "example": {
          "op": "mesh.import",
          "args": {
            "path": "D:/work/out/model.glb",
            "upAxis": "Y",
            "scale": 1
          }
        }
      },
      "data.purge_unused": {
        "mutates": true,
        "destructive": true,
        "summary": "remove datablocks with no users (orphan meshes/materials/images)",
        "args": {
          "dry": {
            "type": "boolean",
            "default": false,
            "note": "report what would be removed without removing it"
          }
        },
        "notes": [
          "deleting an object does not delete its mesh or material; they linger until purge"
        ],
        "example": {
          "op": "data.purge_unused",
          "args": {
            "dry": true
          }
        }
      },
      "file.checkpoint": {
        "mutates": false,
        "summary": "save a snapshot beside the instance (main file untouched, relative paths kept working)",
        "args": {
          "label": {
            "type": "string",
            "default": "checkpoint",
            "charset": "A-Za-z0-9_-.",
            "maxLength": 96
          }
        },
        "notes": [
          "copy=True: bpy.data.filepath is unchanged, so the open file is never modified",
          "relative_remap=True: relative image paths still resolve to the original assets",
          "an existing label is refused (a checkpoint that replaces an earlier one is not a checkpoint)"
        ],
        "example": {
          "op": "file.checkpoint",
          "args": {
            "label": "boy-01"
          }
        }
      },
      "file.stage_export": {
        "mutates": false,
        "summary": "write a standalone copy into the instance staging area for the Host to deliver",
        "args": {
          "name": {
            "type": "string",
            "optional": true,
            "charset": "A-Za-z0-9_-.",
            "maxLength": 96
          }
        },
        "notes": [
          "the staging target is always a fresh name; an existing target is refused",
          "relative_remap=False: relative image paths are reported, not silently rewritten",
          "the final destination is written by the Host (audited, and it refuses to overwrite)"
        ],
        "example": {
          "op": "file.stage_export",
          "args": {}
        }
      }
    },
    "errorCodes": {
      "E_TARGET_EXISTS": "the target file already exists (checkpoints and exports never overwrite)",
      "E_NO_INSTANCE": "the bridge has no instance directory configured",
      "E_UNKNOWN_OP": "op is not in the whitelist",
      "E_BAD_RECORD": "record has unknown/missing keys",
      "E_ARG_TYPE": "a value has the wrong type (or is not finite)",
      "E_ARG_RANGE": "a value is outside its allowed range",
      "E_ARG_ENUM": "a value is not one of the allowed enum members",
      "E_ARG_CHARSET": "a name contains characters outside A-Za-z0-9_-.",
      "E_ARG_MISSING": "a required field is absent",
      "E_NO_SUCH_OBJECT": "the named object does not exist",
      "E_NAME_TAKEN": "the name is already used (pass replace=true to overwrite)",
      "E_NOT_A_MESH": "the object has no mesh data to take a material",
      "E_LIMIT": "a budget was exceeded (ops per batch, objects, materials)",
      "E_BAD_BATCH": "the batch is empty or malformed",
      "E_NO_SUCH_FILE": "the file to import does not exist",
      "E_UNSUPPORTED_FORMAT": "the file format is not supported (imports take .glb/.gltf/.obj, render output takes .png)",
      "E_BYTE_MISMATCH": "the file does not match the size or digest the caller declared",
      "E_NO_MESH_IMPORTED": "the import produced no mesh object (nothing was left behind)",
      "E_NOT_A_CAMERA": "the named object is not a camera",
      "E_ARG_CONFLICT": "two arguments contradict each other",
      "E_INTERNAL": "an operator Blender was asked to run did not finish"
    },
    "notes": [
      "ops are applied in order; the batch stops at the first rejection and reports what already ran",
      "the whole batch shares one undo step",
      "a rejected op changes nothing",
      "read the scene with scene.describe before and after a build to verify the result",
      "capabilitySet names the capability face; primitives is the accepted set for mesh.primitive_add.kind (a UV sphere is published as uv_sphere)"
    ]
  }
}

{
  "ok": true,
  "startedAt": "2026-10-13T15:16:54.255Z",
  "blockers": [],
  "catalog": {
    "version": 1,
    "capabilitySet": "primitives-6.ops-18.limits-64-512",
    "primitives": [
      "cube",
      "uv_sphere",
      "cylinder",
      "cone",
      "torus",
      "plane"
    ],
    "limits": {
      "maxOpsPerBatch": 64,
      "maxObjects": 512,
      "nameCharset": "A-Za-z0-9_-.",
      "nameMaxLength": 96
    },
    "ops": {
